//! File header + section banner emission for `<feature>.gen.ts`.
//!
//! Every emitted feature carries a fixed three-part preamble: a
//! `// Code generated by lazuli; DO NOT EDIT.` line, a comment tagging
//! the source contract, and a runtime-import block referencing
//! `@lazuli/runtime`. Section banners (`Resource:`, `Command: …`,
//! `Query: …`) are emitted between major blocks to make hand-reading
//! the generated TS bearable.
//!
//! Kept in its own module so neighbouring emitters (resource/command/
//! query/lifecycle) consume one canonical banner; if the preamble shape
//! changes, edit it here and every generated file shifts together.

use std::fmt::Write;

use lazuli_codegen_spec::RuntimeFeature;

pub(super) fn write_header(s: &mut String, feature: &RuntimeFeature) {
    writeln!(s, "// Code generated by lazuli; DO NOT EDIT.").ok();
    writeln!(s, "//").ok();
    writeln!(
        s,
        "// Source: {} (feature `{}`)",
        feature.source_path, feature.name
    )
    .ok();
    writeln!(s, "//").ok();
    writeln!(
        s,
        "// This file is hand-written for the runtime spike. Once the runtime API"
    )
    .ok();
    writeln!(
        s,
        "// stabilises, `crates/lazuli_codegen_ts` produces files exactly like this"
    )
    .ok();
    writeln!(
        s,
        "// — types + typed command/query specs — alongside the Go file under"
    )
    .ok();
    writeln!(s, "// `dist/go/customer/customer.gen.go`.").ok();
    writeln!(s).ok();
}

pub(super) fn write_imports(s: &mut String) {
    writeln!(s, "import {{").ok();
    writeln!(s, "  defineCommand,").ok();
    writeln!(s, "  defineQuery,").ok();
    writeln!(s, "  type ID,").ok();
    writeln!(s, "  type Time,").ok();
    writeln!(s, "}} from \"@lazuli/runtime\";").ok();
    writeln!(s).ok();
}

pub(super) fn write_section_banner(s: &mut String, lines: &[String]) {
    writeln!(s, "// {}", "-".repeat(76)).ok();
    for line in lines {
        writeln!(s, "// {line}").ok();
    }
    writeln!(s, "// {}", "-".repeat(76)).ok();
    writeln!(s).ok();
}

pub(super) fn format_string_array(items: &[String]) -> String {
    if items.is_empty() {
        return "[]".to_owned();
    }
    let parts: Vec<String> = items.iter().map(|s| format!("\"{s}\"")).collect();
    format!("[{}]", parts.join(", "))
}
